import java.util.*;

class Solution {
  private static final char[] MOVES = {'U', 'D', 'L', 'R'};
  private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
  private static final int OFFSET = 500, SIZE = 1001;
  private int[][] grid; // 0 unknown, 1 open, 2 target
  private int targetR = -1, targetC = -1;

  public int findShortestPath(GridMaster master) {
    grid = new int[SIZE][SIZE];
    grid[OFFSET][OFFSET] = 1;
    explore(master, OFFSET, OFFSET);
    if (targetR < 0) return -1;
    // the map is known now: plain BFS
    boolean[][] seen = new boolean[SIZE][SIZE];
    Deque<int[]> q = new ArrayDeque<>();
    q.add(new int[] {OFFSET, OFFSET});
    seen[OFFSET][OFFSET] = true;
    for (int steps = 0; !q.isEmpty(); steps++) {
      for (int size = q.size(); size > 0; size--) {
        int[] c = q.poll();
        if (c[0] == targetR && c[1] == targetC) return steps;
        for (int[] d : DIRS) {
          int x = c[0] + d[0], y = c[1] + d[1];
          if (grid[x][y] == 0 || seen[x][y]) continue;
          seen[x][y] = true;
          q.add(new int[] {x, y});
        }
      }
    }
    return -1;
  }

  private void explore(GridMaster master, int r, int c) {
    if (master.isTarget()) {
      targetR = r;
      targetC = c;
    }
    for (int k = 0; k < 4; k++) {
      int x = r + DIRS[k][0], y = c + DIRS[k][1];
      if (grid[x][y] != 0 || !master.canMove(MOVES[k])) continue;
      grid[x][y] = 1;
      master.move(MOVES[k]);
      explore(master, x, y);
      master.move(MOVES[k ^ 1]); // step back (U<->D, L<->R)
    }
  }
}
